    df = pd.concat([ar.rename("a"), sr.rename("s")], axis=1).dropna()
    neg = df[df["s"] < 0]
    b = neg["a"].rolling(60, min_periods=15).cov(neg["s"]) / neg["s"].rolling(60, min_periods=15).var()
