          f"n={m['n_ic_dates']} cov={m['coverage_asset_days']:.3f} to={m['turnover_10_rank']} "
          f"maxlib={m['max_abs_library_correlation']:.4f} => {'PASS' if passed else 'fail'}")
    if passed:
