    results[name] = {"metrics": m, "regime": reg}
    passed = abs(m["ic"]) >= 0.007 and abs(m["icir"]) >= 0.084 and m["max_abs_library_correlation"] < 0.5
    print(f"[{name:26s}] IC={m['ic']:+.4f} ICIR={m['icir']:+.4f} hit={m['ic_hit_ratio']:.3f} "
